// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/instance/settings", wrapper.GetInstanceSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/instance/settings/mail", wrapper.UpdateMailSettings)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/instance/settings/mail/test", wrapper.SendTestMail)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/instance/settings/organizations", wrapper.UpdateOrganizationSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/instance/settings/passwords", wrapper.UpdatePasswordSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/instance/settings/rate-limits", wrapper.UpdateRateLimitSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/instance/settings/logs", wrapper.UpdateLogSettings)
	})

	return r
}

