// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetInstanceSettings Every dashboard setting, with where each value comes from
	// (GET /instance/settings)
	GetInstanceSettings(ctx context.Context, request GetInstanceSettingsRequestObject) (GetInstanceSettingsResponseObject, error)
	// UpdateLogSettings Change how long job logs are kept and how large one attempt's log may grow
	// (PUT /instance/settings/logs)
	UpdateLogSettings(ctx context.Context, request UpdateLogSettingsRequestObject) (UpdateLogSettingsResponseObject, error)
	// UpdateMailSettings Change the mail settings
	// (PUT /instance/settings/mail)
	UpdateMailSettings(ctx context.Context, request UpdateMailSettingsRequestObject) (UpdateMailSettingsResponseObject, error)
	// SendTestMail Send a test email to the caller
	// (POST /instance/settings/mail/test)
	SendTestMail(ctx context.Context, request SendTestMailRequestObject) (SendTestMailResponseObject, error)
	// UpdateOrganizationSettings Choose who may create organizations
	// (PUT /instance/settings/organizations)
	UpdateOrganizationSettings(ctx context.Context, request UpdateOrganizationSettingsRequestObject) (UpdateOrganizationSettingsResponseObject, error)
	// UpdatePasswordSettings Turn the breached-password check on or off
	// (PUT /instance/settings/passwords)
	UpdatePasswordSettings(ctx context.Context, request UpdatePasswordSettingsRequestObject) (UpdatePasswordSettingsResponseObject, error)
	// UpdateRateLimitSettings Change the rate limits
	// (PUT /instance/settings/rate-limits)
	UpdateRateLimitSettings(ctx context.Context, request UpdateRateLimitSettingsRequestObject) (UpdateRateLimitSettingsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

